# detect sampling difference
lines_fmt = [ln for ln in gtexts["parser_sample_differs"].splitlines() if ln.strip()]
lp, sh = grok.detect(lines_fmt)
lp2, sh2 = grok.detect(gtexts["parser_sample_differs"].splitlines())
o.append(f"var wp3DetectSampling = struct {{\n\tfmtName  string\n\tfmtShare float64\n\tparName  string\n}}{{{q(lp.name if lp else '')}, {sh}, {q(lp2.name if lp2 else '')}}}")
